"""Writes the accessory, item resource, job identity and job name fixtures: our own tables shaped like kRO's (EUC-KR
text; bytecode as kRO's client data has it, 32-bit Lua 5.0 and 5.1), large enough to take the parser through big
tables (hundreds of constants, several table constructors' worth). The names the tests look up are the sprite
folders' own; the rest are made up.

    LUAC50=.../luac LUAC51=.../luac python3 make_fixtures.py

Both compilers built for 32 bits (`gcc -m32`) from lua.org's 5.0.3 and 5.1.5 sources.
"""
import os
import subprocess
from pathlib import Path

HERE = Path(__file__).resolve().parent
HEADER = "-- Generated by make_fixtures.py: our own table, shaped like kRO's\n"

ACCESSORIES = {"GOGGLES": (1, "_고글"), "CAP": (14, "_캡"), "RIBBON": (17, "_리본")}
ACCESSORY_FILLER = range(100, 956)
JOBS = {"PORING": (1002, "Poring"), "GOPINICH": (1885, None), "MER_LIF": (6001, "LIF"),
        "MER_FILIR": (6003, "FILIR"), "MER_FILIR_H": (6011, "FILIR_H")}
JOB_FILLER = range(3000, 5100)


def write(name, text):
    (HERE / name).write_bytes(text.encode("euc-kr"))


def accessory_ids():
    rows = [f"\tACCESSORY_{key} = {id}," for key, (id, _) in ACCESSORIES.items()]
    rows += [f"\tACCESSORY_TEST{n} = {n}," for n in ACCESSORY_FILLER]
    # one id with no name: left out of the table
    rows.append("\tACCESSORY_UNNAMED = 99,")
    return HEADER + "ACCESSORY_IDs = {\n" + "\n".join(rows) + "\n}\n"


def accessory_names():
    rows = [f'\t[ACCESSORY_IDs.ACCESSORY_{key}] = "{name}",' for key, (_, name) in ACCESSORIES.items()]
    rows += [f'\t[ACCESSORY_IDs.ACCESSORY_TEST{n}] = "_test{n}",' for n in ACCESSORY_FILLER]
    return HEADER + "AccNameTable = {\n" + "\n".join(rows) + "\n}\n"


def job_identities():
    rows = [f"\tJT_{key} = {id}," for key, (id, _) in JOBS.items()]
    rows += [f"\tJT_TEST{n} = {n}," for n in JOB_FILLER]
    return HEADER + "jobtbl = {\n" + "\n".join(rows) + "\n}\n"


def job_names():
    rows = [f'\t[jobtbl.JT_{key}] = "{name}",' for key, (_, name) in JOBS.items() if name]
    rows += [f'\t[jobtbl.JT_TEST{n}] = "TEST{n}",' for n in JOB_FILLER]
    return HEADER + "JobNameTable = {\n" + "\n".join(rows) + "\n}\n"


def sign_boards():
    # the row with a hole (no text, no colour) as kRO's icons have them
    return HEADER + """SignBoardList = {
	{ "Default", 157, 278, 0, 1, "유저인터페이스\\\\collection\\\\꽃가지.bmp", "기본", "#0x009EBDFF" },
	{ "prontera", 146, 89, 0, 1, "유저인터페이스\\\\information\\\\over_kafra.bmp" },
	{ "prontera", 134, 184, 15, 3, "item\\\\test.bmp", "시험 간판", "#0x00FFFFFF" },
}
"""


def item_resources():
    return ("// Generated by make_fixtures.py: our own table, shaped like kRO's\n"
            "501#빨간포션#\n664#선물상자_1#\n// a comment\n502##\nnot-an-id#x#\n")


def compile_lub(luac, source, out):
    subprocess.run([luac, "-o", str(HERE / out), str(HERE / source)], check=True)


def main():
    write("accessoryid.lua", accessory_ids())
    write("accname.lua", accessory_names())
    write("jobidentity.lua", job_identities())
    write("jobname.lua", job_names())
    write("idnum2itemresnametable.txt", item_resources())
    write("signboardlist.lua", sign_boards())
    for version, luac in (("50", os.environ["LUAC50"]), ("51", os.environ["LUAC51"])):
        compile_lub(luac, "accessoryid.lua", f"acid_lua{version}.lub")
        compile_lub(luac, "accname.lua", f"aname_lua{version}.lub")
        compile_lub(luac, "jobidentity.lua", f"npcid_lua{version}.lub")
    compile_lub(os.environ["LUAC51"], "jobname.lua", "jname_lua51.lub")
    compile_lub(os.environ["LUAC51"], "signboardlist.lua", "signboardlist_lua51.lub")


if __name__ == "__main__":
    main()
